package com.mendes.scheduling_platform.platform; import com.mendes.scheduling_platform.booking.BookingRepository; import com.mendes.scheduling_platform.exception.NotFoundException; import com.mendes.scheduling_platform.subscription.*; import com.mendes.scheduling_platform.tenant.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*;
@RestController @RequestMapping("/platform/admin") public class PlatformAdminController {private final TenantRepository tenants;private final SubscriptionRepository subscriptions;private final BookingRepository bookings;public PlatformAdminController(TenantRepository t,SubscriptionRepository s,BookingRepository b){tenants=t;subscriptions=s;bookings=b;}public record Metrics(long tenants,long activeTenants,long subscriptions,long bookings,BigDecimal grossBookingValue){}@GetMapping("/tenants") List<Tenant> tenants(){return tenants.findAll();}@GetMapping("/metrics") Metrics metrics(){List<Tenant> ts=tenants.findAll();var bs=bookings.findAll();return new Metrics(ts.size(),ts.stream().filter(t->t.getStatus()==Tenant.TenantStatus.ACTIVE).count(),subscriptions.count(),bs.size(),bs.stream().map(x->x.getTotalAmount()==null?BigDecimal.ZERO:x.getTotalAmount()).reduce(BigDecimal.ZERO,BigDecimal::add));}@PatchMapping("/tenants/{id}/suspension") Tenant suspension(@PathVariable Long id,@RequestParam boolean suspended){Tenant t=tenants.findById(id).orElseThrow(()->new NotFoundException("Tenant não encontrado"));t.setStatus(suspended?Tenant.TenantStatus.SUSPENDED:Tenant.TenantStatus.ACTIVE);return tenants.save(t);}@PutMapping("/tenants/{id}/subscription") Subscription subscription(@PathVariable Long id,@RequestBody Subscription in){Tenant t=tenants.findById(id).orElseThrow(()->new NotFoundException("Tenant não encontrado"));Subscription s=subscriptions.findByTenantId(id).orElseGet(Subscription::new);s.setTenantId(id);s.setPlan(in.getPlan());s.setStatus(in.getStatus());s.setStartDate(in.getStartDate());s.setEndDate(in.getEndDate());t.setPlan(in.getPlan());tenants.save(t);return subscriptions.save(s);}}
